{
  "critique": [
    {
      "design": "r1A",
      "good": "கோயில், நகரம், இரண்டு நேர வரம்புகளும் முதல் பார்வையில் தெரிகின்றன. பெயர்களும் நேர வரம்புகளும் உடையாமல், வரிசைகள் சீரான தாளத்தில் அமைந்துள்ளன.",
      "problems": "சிறப்புப் பகுதியைப் படிக்கப் பக்கவாட்டில் நகர்த்த வேண்டும்; நீண்ட உரை காரணமாக மற்ற செல்களில் அதிக வெற்றிடம் உள்ளது. நேரத் தலைப்பு இரண்டு வரிகளில் உள்ளது.",
      "cause": "முதல் மூன்று பத்திகள் மொத்தம் 358px எடுத்துக்கொள்வதால் சிறப்புப் பத்தி கிட்டத்தட்ட முழுவதும் பார்வைப் பெட்டிக்கு வெளியே உள்ளது. 240px சிறப்புப் பத்தி உரையை ஆறு வரிகள் வரை மடிக்கிறது; 110px நேரப் பத்தியில் தலைப்பு மடிகிறது."
    },
    {
      "design": "r1B",
      "good": "பெயர்களும் நேர வரம்புகளும் உடையவில்லை; முதல் மூன்று பத்திகளும் பார்வைப் பெட்டிக்குள் அடங்குகின்றன. மூன்று வடிவங்களில் பக்கவாட்டு நகர்வு குறைவு.",
      "problems": "சிறப்புரைகள் எட்டு வரிகள் வரை நீண்டு, அட்டவணை மிகவும் உயரமாகிறது; அதனால் குறுகிய நகரம் மற்றும் நேரச் செல்களுக்கு அடியில் பெரும் வெற்றிடம் தோன்றுகிறது. முதல் கோயில் பெயரும் மூன்று வரிகளாகிறது.",
      "cause": "200px சிறப்புப் பத்தி நீண்ட உரைக்கு மிகவும் குறுகலாக உள்ளது. 119px கோயில் பத்தியில் முதல் பெயரின் சொற்கள் ஒன்றாக அடங்காமல் தனித்தனி வரிகளாகின்றன."
    },
    {
      "design": "r1C",
      "good": "தலைப்புகள் ஒரே வரியில் உள்ளன; சிறப்புரைக்குக் கூடுதல் இடம் வழங்கியதால் வரிசைகள் மற்ற வடிவங்களைவிடக் குறைவான உயரத்தில் உள்ளன. சொற்களும் நேர வரம்புகளும் உடையவில்லை.",
      "problems": "முதல் பார்வையில் நேரப் பத்தி நடுவே துண்டிக்கப்படுகிறது; முழு நேரத்தையும் சிறப்பையும் காண அதிகமாகப் பக்கவாட்டில் நகர்த்த வேண்டும். நேரங்களை வரிசையாக ஒப்பிடுவதும் தொடக்கப் பார்வையில் கடினம்.",
      "cause": "196px நேரப் பத்தி இரண்டு வரம்புகளையும் ஒரே வரியில் வைக்கிறது; ஆனால் முதல் இரண்டு பத்திகளுக்குப் பிறகு பார்வைப் பெட்டியில் 112px மட்டுமே மீதமுள்ளது. 300px சிறப்புப் பத்தியுடன் மொத்த அகலம் 745px ஆகிறது."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "A-wide-description",
      "widths": [130, 118, 110, 300],
      "change": "r1A-வின் முதல் பார்வையில் தெரியும் அடையாளம் மற்றும் நேரப் பத்திகளை வைத்துக்கொண்டு சிறப்புப் பத்தியை அகலப்படுத்துகிறது. கூடுதல் பக்கவாட்டு நகர்வுக்குப் பதிலாக உரை மடிப்பையும் வரிசை உயரத்தையும் குறைக்க முயல்கிறது."
    },
    {
      "name": "balanced-first-view",
      "widths": [119, 118, 122, 260],
      "change": "முதல் மூன்று பத்திகளையும் 359px-க்குள் வைத்து நேரப் பத்திக்கு சிறிது கூடுதல் இடம் அளிக்கிறது; சிறப்புரைக்கு r1B-ஐவிட அதிக இடம் தருகிறது. குறுகிய கோயில் பத்தியில் முதல் பெயரின் மடிப்பு மற்றும் தலைப்பு மடிப்பைச் சரிபார்க்கலாம்."
    },
    {
      "name": "compact-scroll",
      "widths": [130, 118, 110, 260],
      "change": "r1A-வை சிறிதளவு மட்டும் அகலப்படுத்தி, சிறப்புரையின் மடிப்பைக் குறைப்பதற்கும் பக்கவாட்டு நகர்வைக் கட்டுப்படுத்துவதற்கும் இடைநிலைத் தீர்வைச் சோதிக்கிறது."
    }
  ]
}
